// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme  "Show Your Work" (Improve some of your earliest creative coding).

At the time I coded the original shader, I was experimenting with truchet
patterns and watched Martijn Steinrucken's YT video on the subject in which
he used the Minkowski Distance. I was immediately hooked and looked for
inspiration. Luckily, I was in Venice at the time and did a lot of window
shopping. Stuff like this was everywhere. My shader "Treasure in the Belly
Store" was what I came up with.
Spirals came to my mind when @pumaparded (Tom Hinton) released his shader
"I'm running towards nothing". I thought I had to incorporate it into my
shader somehow. Just to make it more interesting.
Getting that metallic shine on the screen had been bugging me for a long time.
Using white noise to mix gold and bronze, I thought, could do the job.

The remake incorporates all of the above. The deforming figure using the
Minkowski Distance, the spiral and the metallic shine. To improve it, I added
another metallic appearance. This time a procedurally generated rust-like
material. I also framed it, which by the way is reminiscent of the original
version, by using white noise to mix in some gold glitter.

Treasure in the Belly Store
https://codepen.io/atzedent/details/abYepPV

I'm running towards nothing
https://codepen.io/TomHinton/details/gOeqvVa
*/

let theShader, dpr = window.devicePixelRatio, ww = window.innerWidth*dpr, wh = window.innerHeight*dpr, startRandom;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2469732/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
	startRandom = Math.random();
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader);

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; gl.enable(gl.DEPTH_TEST); gl.depthFunc(gl.LEQUAL);
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* Remake of my shader "Treasure in the Belly Store" (August 30, 2022)
* https://codepen.io/atzedent/details/abYepPV
*/
precision highp float;
out vec4 O;
uniform vec2 resolution;
uniform float time;
#define FC gl_FragCoord.xy
#define R resolution
#define T (2.8+time)
#define S smoothstep
#define N normalize
#define MN min(R.x,R.y)
#define TAU radians(360.)
#define hue(a) (.6+.6*cos(TAU*(a)-vec3(0,83,21)))
#define gold vec3(255,233,152)/255.
#define bron vec3(87,55,13)/255.
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
// Returns a pseudo random number for a given point (white noise)
float rnd(vec2 p) {
  p=fract(p*vec2(12.9898,78.233));
  p+=dot(p,p+34.56);
  return fract(p.x*p.y);
}
// Returns a pseudo random number for a given point (value noise)
float noise(in vec2 p) {
  vec2 i=floor(p), f=fract(p), u=f*f*(3.-2.*f);
  float
  a=rnd(i),
  b=rnd(i+vec2(1,0)),
  c=rnd(i+vec2(0,1)),
  d=rnd(i+1.);
  return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
// Returns a pseudo random number for a given point (fractal noise)
float fbm(vec2 p) {
  float t=.0, a=1.; mat2 m=mat2(1.6,-.6,.2,1.6);
  for (int i=0; i<5; i++) {
    t+=a*noise(p);
    p*=m*2.;
    a*=.5;
  }
  return t;
}
// Returns a rust like pattern by using fBm(x)->fBm(x*fBm(x*fBm(x)))
vec3 pattern(vec2 uv) {
  vec3 col=vec3(0);
  vec2 p=uv;
  float d=1., t=-T*.0025;
  for (float i=.0; i<3.; i++) {
    p=vec2(cos(.125*sin(uv.x)),sin(uv.y)*.25);
    float
    k=p.x+p.y;
    d=fbm(8.*(uv-p)*k*d);
    uv*=.5;
    col+=hue(d)/3.;
  }
  col=mix(col,vec3(.5),.35);
  col=mix(col,col*col*col*col,col);
  col=S(.0,1.,col);
  col=pow(col,vec3(.4545));
  return col;
}
// Returns the Minkowski distance of the given point with the given exponent
float cLength(vec2 p, float k) {
  p = abs(p);
  return pow(pow(p.x, k) + pow(p.y, k), 1./k);
}
// Returns the sdf of a spiral at the given point with the given scaling factor
float spiral(in vec2 p, in float t) {
  float r=dot(p, p), a=atan(p.y, p.x)/TAU;
  return sin(fract(.05/(r+.01)*t+a));
}
// Returns a circle at a given point with the given radius, width, blur and exponent for the Minkowsky distance
float circle(in vec2 p, in float r, in float w, in float b, in float k) {
  float d=cLength(p,k);
  return S(b,-b,abs(d-r)-w);
}
// The main entry point of the shader
void main(void) {
  vec2 uv=(FC-.5*R)/MN;
  // px for anti aliasing, bs for frame border, alpha for the shadow movement, rhm for the deformation animation, ch for the exponent of the Minkowski distance
  float px=1./MN, bs=MN*.05, alpha=sin(T), rhm=S(1.,.0,.5+.5*sin(T)), ch=.8+rhm*1.2,
  // construct the deforming figure
  fig=circle(uv,.25,.125,px,ch),
  // construct the fake shadow (just a copy of the figure)
	shadow=circle(uv-vec2(-.03,0)*rot(.5-1.*alpha),.255-(.025-rhm*.025),.1,px*(40.+rhm*20.),ch),
	// constuct the spiral
  spiral=spiral(uv*rot(10.*(.5+.5*cos(T))),.118+rhm),
  // create the spiral's animation
  anima=sin(exp(-clamp(log(spiral),-3.,.0)));
  // the next two lines create the fake shadows on the figure with a checker board pattern and some noise
	vec2 p=fract(uv*2.);
	float g=mod(p.x+p.y,2.), n=g*pow(noise(uv*3.4-vec2(.3,-.05)),2.)*anima;
	vec3
	// mix the color for the figure
	c=mix(gold,bron,n),
	// add the rusty background pattern
	col=mix(pattern(FC/MN),mix(gold,bron,noise(uv*2.)*(anima*(.5*dot(uv,uv)))),.5);
	// darken the figure's color to emphasize the dark patches
	c/=1.+exp(-c*c);
	// darken the background for more contrast
	col/=1.+exp(-col*col*col);
	// add the fake shadow
  col=mix(col,vec3(0),min(shadow,.65));
  // add the figure
  col=mix(col,c,fig);
  // create a border
  if (FC.x > R.x-bs || FC.x < bs || FC.y > R.y-bs || FC.y < bs) {
  	// get a random value
  	float r=rnd(uv);
  	// add a fair bit of bronze
    col=mix(col, bron, mix(.6,.7,noise(r*uv*84.)));
    // add a tad bit of some brighter gold
    col=mix(gold, col, mix(.8,1.,noise(fract(r*12.34)*uv*4.)));
    // darken the result for more contrast
		col/=1.+exp(-col);
		// brigthen again
		col=sqrt(col);
  }
  // output the pixel's color to the screen
  O=vec4(col,1);
}

